"""Render a contribution activity graph (last N days) as a themed SVG.

Replaces the third-party github-readme-activity-graph service so the image is
generated by our own workflow and served from the `output` branch.

Usage: python activity_graph.py <output.svg>
"""

from __future__ import annotations

import json
import os
import sys
import urllib.request
from datetime import date
from pathlib import Path

USERNAME = os.environ.get("GITHUB_REPOSITORY_OWNER", "AmirKenzo")
DAYS = 31

WIDTH, HEIGHT = 1200, 360
PAD_LEFT, PAD_RIGHT, PAD_TOP, PAD_BOTTOM = 70, 30, 60, 60
BG = "#0d1117"
GRID = "#1b2a22"
TEXT = "#8b949e"
TITLE = "#00ff88"
LINE = "#00c647"
POINT = "#ffffff"

QUERY = """
query($login: String!) {
  user(login: $login) {
    contributionsCollection {
      contributionCalendar {
        weeks { contributionDays { date contributionCount } }
      }
    }
  }
}
"""


def fetch_days(token: str) -> list[tuple[date, int]]:
    payload = json.dumps({"query": QUERY, "variables": {"login": USERNAME}}).encode()
    request = urllib.request.Request(
        "https://api.github.com/graphql",
        data=payload,
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        },
    )
    with urllib.request.urlopen(request, timeout=30) as response:
        body = json.load(response)
    if "errors" in body:
        raise RuntimeError(f"GraphQL error: {body['errors']}")
    weeks = body["data"]["user"]["contributionsCollection"]["contributionCalendar"][
        "weeks"
    ]
    days = [
        (date.fromisoformat(d["date"]), d["contributionCount"])
        for week in weeks
        for d in week["contributionDays"]
    ]
    return days[-DAYS:]


def nice_max(value: int) -> int:
    """Round the y-axis ceiling up to a value divisible into 5 even steps."""
    if value <= 5:
        return 5
    step = 1
    while value / step > 50:
        step *= 10
    return -(-value // (5 * step)) * 5 * step


def render_svg(days: list[tuple[date, int]]) -> str:
    chart_w = WIDTH - PAD_LEFT - PAD_RIGHT
    chart_h = HEIGHT - PAD_TOP - PAD_BOTTOM
    top = nice_max(max((c for _, c in days), default=0))
    x_step = chart_w / max(len(days) - 1, 1)

    def xy(i: int, count: int) -> tuple[float, float]:
        return PAD_LEFT + i * x_step, PAD_TOP + chart_h - count / top * chart_h

    points = [xy(i, c) for i, (_, c) in enumerate(days)]
    line = " ".join(f"{x:.1f},{y:.1f}" for x, y in points)
    base = PAD_TOP + chart_h
    area = (
        f"{PAD_LEFT:.1f},{base:.1f} {line} {points[-1][0]:.1f},{base:.1f}"
        if points
        else ""
    )

    parts = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{WIDTH}" height="{HEIGHT}" '
        f'viewBox="0 0 {WIDTH} {HEIGHT}" font-family="Segoe UI, Ubuntu, sans-serif">',
        "<defs>",
        '<linearGradient id="area" x1="0" y1="0" x2="0" y2="1">',
        f'<stop offset="0%" stop-color="{LINE}" stop-opacity="0.45"/>',
        f'<stop offset="100%" stop-color="{LINE}" stop-opacity="0"/>',
        "</linearGradient>",
        '<clipPath id="reveal"><rect x="0" y="0" width="0" height="100%">'
        f'<animate attributeName="width" from="0" to="{WIDTH}" dur="1.6s" fill="freeze"/>'
        "</rect></clipPath>",
        "</defs>",
        f'<rect width="100%" height="100%" rx="8" fill="{BG}"/>',
        f'<text x="{WIDTH / 2}" y="36" text-anchor="middle" fill="{TITLE}" font-size="20" '
        f'font-weight="600">{USERNAME}\'s Contribution Graph</text>',
    ]
    for step in range(6):
        value = top * step // 5
        y = PAD_TOP + chart_h - chart_h * step / 5
        parts.append(
            f'<line x1="{PAD_LEFT}" y1="{y:.1f}" x2="{WIDTH - PAD_RIGHT}" y2="{y:.1f}" '
            f'stroke="{GRID}" stroke-dasharray="4 4"/>'
        )
        parts.append(
            f'<text x="{PAD_LEFT - 12}" y="{y + 4:.1f}" text-anchor="end" fill="{TEXT}" '
            f'font-size="12">{value}</text>'
        )
    for (day, _), (x, _) in zip(days, points):
        parts.append(
            f'<text x="{x:.1f}" y="{base + 22:.1f}" text-anchor="middle" fill="{TEXT}" '
            f'font-size="12">{day.day}</text>'
        )
    parts.append(
        f'<text x="{WIDTH / 2}" y="{HEIGHT - 10}" text-anchor="middle" fill="{TEXT}" '
        f'font-size="12">Last {len(days)} days</text>'
    )
    parts.append('<g clip-path="url(#reveal)">')
    if points:
        parts.append(f'<polygon points="{area}" fill="url(#area)"/>')
        parts.append(
            f'<polyline points="{line}" fill="none" stroke="{LINE}" stroke-width="2.5" '
            'stroke-linejoin="round" stroke-linecap="round"/>'
        )
    for (day, count), (x, y) in zip(days, points):
        parts.append(
            f'<circle cx="{x:.1f}" cy="{y:.1f}" r="3.5" fill="{POINT}" stroke="{LINE}" '
            f'stroke-width="1.5"><title>{day.isoformat()}: {count}</title></circle>'
        )
    parts.append("</g></svg>")
    return "\n".join(parts)


def main() -> int:
    if len(sys.argv) != 2:
        print("Usage: activity_graph.py <output.svg>", file=sys.stderr)
        return 2
    token = os.environ.get("GITHUB_TOKEN")
    if not token:
        print("GITHUB_TOKEN is required for the GraphQL API", file=sys.stderr)
        return 1
    out = Path(sys.argv[1])
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(render_svg(fetch_days(token)), encoding="utf-8")
    print(f"Wrote {out}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
